-- Eight uploaded product displays. Prices and currencies were not confirmed.
begin;
insert into public.products(id,store_id,name,description,price,image,section,available,translations)
select r.id,s.id,r.name,r.description,null,r.image,r.section,true,r.translations
from jsonb_to_recordset($products$[{"id": "bdb2c641-36fd-5d5a-9a07-d1de03efef6f", "name": "مرطبانات زجاجية مضلعة مع حامل متدرج", "description": "مرطبانات شفافة مضلعة بأغطية ومقابض علوية مزخرفة، مع حامل متدرج بلون خشبي كما في الصورة.", "section": "منظمات منزلية", "image": "https://damascus-shop.com/images/happy-house/20261101/30018.jpg", "translations": {"en": {"name": "Ribbed glass jars with tiered stand"}, "de": {"name": "Geriffelte Glasbehälter mit Stufenständer"}}}, {"id": "2437dfd9-2615-55cf-bb1b-edc28e4c2b3c", "name": "صواني ضيافة دائرية بمقابض ذهبية", "description": "صوانٍ دائرية بأحجام متدرجة، بسطح فضي وحواف مزخرفة ومقابض باللون الذهبي.", "section": "أدوات ضيافة", "image": "https://damascus-shop.com/images/happy-house/20261101/30015.jpg", "translations": {"en": {"name": "Round serving trays with gold handles"}, "de": {"name": "Runde Serviertabletts mit goldfarbenen Griffen"}}}, {"id": "63d195a0-ac13-508a-b151-0a090213332a", "name": "أباريق شاي ملونة بمقابض علوية", "description": "أباريق شاي بأغطية ومقابض علوية، بالألوان الرمادي والأبيض والأسود ونقوش متنوعة كما في الصورة.", "section": "أدوات ضيافة", "image": "https://damascus-shop.com/images/happy-house/20261101/30012.jpg", "translations": {"en": {"name": "Coloured tea kettles with top handles"}, "de": {"name": "Farbige Teekessel mit Bügelgriffen"}}}, {"id": "b02343d3-37fd-5797-9a88-7357d6a90d8b", "name": "صواني ضيافة مستطيلة بنقوش زهور", "description": "صوانٍ مستطيلة بأحجام متنوعة وحواف مزخرفة باللون الذهبي، مع مقابض جانبية ونقوش زهور.", "section": "أدوات ضيافة", "image": "https://damascus-shop.com/images/happy-house/20261101/30009.jpg", "translations": {"en": {"name": "Rectangular serving trays with floral patterns"}, "de": {"name": "Rechteckige Serviertabletts mit Blumenmustern"}}}, {"id": "892b2fb2-996a-52d4-b930-20318a1db0d6", "name": "مرطبانات الشاي والقهوة والسكر بأغطية خشبية", "description": "مرطبانات زجاجية شفافة مخصصة للشاي والقهوة والسكر، بكتابات توضيحية وأغطية خشبية بمقابض دائرية.", "section": "منظمات منزلية", "image": "https://damascus-shop.com/images/happy-house/20261101/30006.jpg", "translations": {"en": {"name": "Tea coffee and sugar jars with wooden lids"}, "de": {"name": "Tee-, Kaffee- und Zuckergläser mit Holzdeckeln"}}}, {"id": "ab03d678-e4d9-52c8-9a7c-e68a9c9413d8", "name": "صواني ضيافة بحواف متموجة ذهبية وفضية", "description": "صوانٍ مستطيلة بأحجام متدرجة وحواف متموجة مزخرفة باللونين الذهبي والفضي، مع مقابض جانبية.", "section": "أدوات ضيافة", "image": "https://damascus-shop.com/images/happy-house/20261101/30003.jpg", "translations": {"en": {"name": "Serving trays with gold and silver scalloped edges"}, "de": {"name": "Serviertabletts mit gold- und silberfarbenen Wellenrändern"}}}, {"id": "0f9ceaf7-7ce8-53fe-aacc-ef3dcfa5d53e", "name": "مرطبانات زجاجية بأغطية مزينة بغزال ذهبي", "description": "مرطبانات شفافة ذات نقوش بارزة، بأغطية فاتحة ومقابض علوية بشكل غزال باللون الذهبي.", "section": "منظمات منزلية", "image": "https://damascus-shop.com/images/happy-house/20261101/30000.jpg", "translations": {"en": {"name": "Glass jars with gold deer lid handles"}, "de": {"name": "Glasbehälter mit goldfarbenen Hirschgriffen"}}}, {"id": "be5efb3e-f889-562e-ae45-d9d0aeeb8b6d", "name": "مرطبانات سوداء بزخارف ذهبية", "description": "مجموعة مرطبانات سوداء بأحجام متدرجة وزخارف ذهبية، مع أغطية مزخرفة ومقابض علوية باللون الذهبي.", "section": "منظمات منزلية", "image": "https://damascus-shop.com/images/happy-house/20261101/29997.jpg", "translations": {"en": {"name": "Black storage jars with gold patterns"}, "de": {"name": "Schwarze Vorratsbehälter mit goldenen Mustern"}}}]$products$::jsonb)
as r(id uuid,name text,description text,section text,image text,translations jsonb)
cross join public.stores s where s.id='c0a627c1-229d-4da9-957c-4aff3ff48a8f' and s.active and s.deleted_at is null
on conflict(id) do nothing;
commit;
